  "fb": "Pseudozientziaren defentsa gustukoena ezjakintasunari deia da: «inork ez du frogatu funtzionatzen ez dutenik». Baina frogatzea baieztatzen duenari dagokio, eta kontrako frogarik ez izateak ez du esan nahi aldeko frogarik dagoenik.",
