   "Morala komunitate batek bizi dituen arauak dira; etikak filosofikoki hausnartzen du haien gainean.",
   "Etika erlijio-arauen multzoa da eta morala arau zibilen multzoa.",
   "Morala hausnarketa indibiduala da eta etika ohitura kolektiboa."
