  "fb": "Humek «gustatzen zait» (hobespena, eztabaidaezina) eta «ona da» (judizioa, arrazoiak onartzen dituena) bereizten ditu; lehenengotik bigarrenera arrazoirik eman gabe pasatzea nahastea da.",
